function rampartSimulate(createStrategy, seed, maxTicks, obs) {
  var TT = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
  var TD = {
    bolt: { cost: 50, dmg: 26, per: 8, range: 300, splash: 0, slow: 0, pierce: 0, ground: 1, air: 1 },
    cannon: { cost: 90, dmg: 60, per: 24, range: 260, splash: 90, slow: 0, pierce: 0, ground: 1, air: 0 },
    frost: { cost: 70, dmg: 10, per: 12, range: 240, splash: 0, slow: 30, pierce: 0, ground: 1, air: 1 },
    lance: { cost: 120, dmg: 180, per: 36, range: 360, splash: 0, slow: 0, pierce: 1, ground: 1, air: 0 },
    flak: { cost: 80, dmg: 40, per: 10, range: 320, splash: 70, slow: 0, pierce: 0, ground: 0, air: 1 }
  };
  var ET = {
    grunt: { hp: 60, sp: 10, bounty: 4, leak: 1, air: 0, first: 1, wt: 10 },
    runner: { hp: 40, sp: 20, bounty: 4, leak: 1, air: 0, first: 2, wt: 4 },
    wisp: { hp: 50, sp: 12, bounty: 6, leak: 2, air: 1, first: 3, wt: 3 },
    brute: { hp: 150, sp: 6, bounty: 9, leak: 3, air: 0, first: 4, wt: 3 },
    splitter: { hp: 90, sp: 8, bounty: 6, leak: 2, air: 0, first: 6, wt: 2 },
    mender: { hp: 70, sp: 8, bounty: 7, leak: 2, air: 0, first: 8, wt: 1 },
    splitling: { hp: 0, sp: 12, bounty: 1, leak: 1, air: 0, first: 99, wt: 0 }
  };
  var ORDER = ['grunt', 'runner', 'wisp', 'brute', 'splitter', 'mender'];
  var SLOTS = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8], [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];
  function mkRoute(pts) {
    var p = pts.map(function (q) { return [q[0] * 100 + 50, q[1] * 100 + 50]; });
    var cum = [0];
    for (var i = 1; i < p.length; i++) cum.push(cum[i - 1] + Math.abs(p[i][0] - p[i - 1][0]) + Math.abs(p[i][1] - p[i - 1][1]));
    return { p: p, cum: cum, len: cum[cum.length - 1] };
  }
  var ROUTES = [
    mkRoute([[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]]),
    mkRoute([[0, 6], [21, 6], [21, 11], [23, 11]])
  ];
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
  function posAt(r, prog) {
    var i = 1;
    while (i < r.cum.length - 1 && prog > r.cum[i]) i++;
    var a = r.p[i - 1], b = r.p[i], d = r.cum[i] - r.cum[i - 1];
    var f = Math.min(prog - r.cum[i - 1], d);
    if (f < 0) f = 0;
    var dx = b[0] - a[0], dy = b[1] - a[1];
    return [a[0] + (dx > 0 ? f : dx < 0 ? -f : 0), a[1] + (dy > 0 ? f : dy < 0 ? -f : 0)];
  }
  var mArr = [0, 1000];
  function mult(w) { while (mArr.length <= w) mArr.push(Math.floor(mArr[mArr.length - 1] * 108 / 100)); return mArr[w]; }
  var rng = mulberry32(seed);
  var waves = [];
  function genWave(w) {
    var list = [], types = [], sum = 0, i;
    for (i = 0; i < ORDER.length; i++) if (ET[ORDER[i]].first <= w) { types.push(ORDER[i]); sum += ET[ORDER[i]].wt; }
    var n = 4 + Math.floor(3 * w / 5);
    for (i = 0; i < n; i++) {
      var r = rng() % sum, k = 0;
      while (r >= ET[types[k]].wt) { r -= ET[types[k]].wt; k++; }
      list.push(types[k]);
    }
    return list;
  }
  var strat = createStrategy();
  var log = [];
  var gold = 250, baseHp = 10, nextId = 1, curWave = 0, fallTick = -1;
  var turrets = new Array(16).fill(null);
  var enemies = [];
  var spawnQ = {};
  function mkEnemy(type, wave, maxHp, prog) {
    var d = ET[type];
    var armor = type === 'grunt' ? Math.floor(wave / 4) : type === 'brute' ? 6 + wave : 0;
    return { id: nextId++, type: type, wave: wave, hp: maxHp, maxHp: maxHp, prog: prog, age: 0, slow: 0, air: d.air, armor: armor, sp: d.sp, route: ROUTES[d.air], dead: false };
  }
  function view(e) {
    var p = posAt(e.route, e.prog);
    return { id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp, x: p[0], y: p[1], air: e.air, armor: e.armor, speed: e.slow > 0 ? Math.floor(e.sp * 60 / 100) : e.sp, slowed: e.slow > 0 ? 1 : 0, remaining: e.route.len - e.prog };
  }
  function hash(l) {
    var s = JSON.stringify(l), h = 0x811c9dc5;
    for (var i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193); }
    return ('00000000' + (h >>> 0).toString(16)).slice(-8);
  }
  function tdmg(t) { var d = TD[t.type].dmg; for (var i = 1; i < t.tier; i++) d = Math.floor(d * 16 / 10); return d; }
  function trange(t) { return TD[t.type].range + 30 * (t.tier - 1); }
  waves[1] = genWave(1);
  var done = false;
  for (var tick = 0; tick < maxTicks && !done; tick++) {
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      var w = (tick - 20) / 40 + 1;
      curWave = w;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * w;
      waves[w + 1] = genWave(w + 1);
      var st = { tick: tick, wave: w, gold: gold, baseHp: baseHp, slots: [], enemies: enemies.map(view), nextWave: waves[w + 1].slice() };
      for (var s = 0; s < 16; s++) {
        var t0 = turrets[s];
        st.slots.push({ slot: s, x: SLOTS[s][0], y: SLOTS[s][1], turret: t0 ? { type: t0.type, tier: t0.tier, spent: t0.spent } : null });
      }
      var acts = null;
      acts = strat.plan(st);
      if (Array.isArray(acts)) {
        if (acts.length > 32) acts = acts.slice(0, 32);
        for (var ai = 0; ai < acts.length; ai++) {
          var a = acts[ai];
          if (!a || typeof a !== 'object') continue;
          var sl = a.slot;
          if (!(sl >= 0 && sl < 16) || Math.floor(sl) !== sl) continue;
          var tu = turrets[sl];
          if (a.op === 'build') {
            var ti = TT.indexOf(a.type);
            if (tu || ti < 0 || typeof a.type !== 'string') continue;
            var c = TD[a.type].cost;
            if (gold < c) continue;
            gold -= c;
            turrets[sl] = { type: a.type, tier: 1, spent: c, cd: 0 };
            log.push([tick, 'B', sl, ti]);
            if (obs && obs.build) obs.build(tick, sl, ti);
          } else if (a.op === 'upgrade') {
            if (!tu || tu.tier >= 3) continue;
            var uc = TD[tu.type].cost * (tu.tier === 1 ? 1 : 2);
            if (gold < uc) continue;
            gold -= uc; tu.spent += uc; tu.tier++;
            log.push([tick, 'U', sl, tu.tier]);
            if (obs && obs.upgrade) obs.upgrade(tick, sl, tu.tier);
          } else if (a.op === 'sell') {
            if (!tu) continue;
            gold += Math.floor(tu.spent * 70 / 100);
            turrets[sl] = null;
            log.push([tick, 'S', sl, 0]);
            if (obs && obs.sell) obs.sell(tick, sl);
          }
        }
      }
      var comp = waves[w];
      for (var i = 0; i < comp.length; i++) {
        var tt = tick + 4 * i;
        (spawnQ[tt] || (spawnQ[tt] = [])).push([w, comp[i]]);
      }
    }
    var sq = spawnQ[tick];
    if (sq) {
      for (var i = 0; i < sq.length; i++) {
        var wv = sq[i][0], ty = sq[i][1];
        enemies.push(mkEnemy(ty, wv, Math.floor(ET[ty].hp * mult(wv) / 1000), 0));
      }
      delete spawnQ[tick];
    }
    // move
    var alive = [];
    for (var i = 0; i < enemies.length; i++) {
      var e = enemies[i];
      e.prog += e.slow > 0 ? Math.floor(e.sp * 60 / 100) : e.sp;
      if (e.prog >= e.route.len) {
        baseHp -= ET[e.type].leak;
        log.push([tick, 'L', e.id, baseHp]);
        if (obs && obs.leak) obs.leak(tick, e);
        if (baseHp <= 0) { fallTick = tick; log.push([tick, 'F', curWave, 0]); done = true; break; }
      } else alive.push(e);
    }
    if (done) break;
    enemies = alive;
    // age & heal
    for (var i = 0; i < enemies.length; i++) {
      var e = enemies[i];
      e.age++;
      if (e.type === 'mender' && e.age % 20 === 0) {
        var mp = posAt(e.route, e.prog);
        for (var j = 0; j < enemies.length; j++) {
          var o = enemies[j];
          var op = posAt(o.route, o.prog);
          var dx = op[0] - mp[0], dy = op[1] - mp[1];
          if (dx * dx + dy * dy <= 150 * 150) o.hp = Math.min(o.maxHp, o.hp + Math.floor(o.maxHp * 8 / 100));
        }
        if (obs && obs.heal) obs.heal(tick, mp[0], mp[1], e.id);
      }
    }
    // fire
    for (var s = 0; s < 16; s++) {
      var tu = turrets[s];
      if (!tu) continue;
      if (tu.cd > 0) tu.cd--;
      if (tu.cd > 0) continue;
      var td = TD[tu.type], rg = trange(tu), r2 = rg * rg;
      var tp = SLOTS[s], tx = tp[0] * 100 + 50, ty2 = tp[1] * 100 + 50;
      var cands = [], cpos = [];
      for (var i = 0; i < enemies.length; i++) {
        var e = enemies[i];
        if (e.hp <= 0) continue;
        if (e.air ? !td.air : !td.ground) continue;
        var p = posAt(e.route, e.prog);
        var dx = p[0] - tx, dy = p[1] - ty2;
        if (dx * dx + dy * dy <= r2) { cands.push(e); cpos.push(p); }
      }
      if (!cands.length) continue;
      var pick = -1;
      if (strat.target) {
        var tv = { slot: s, type: tu.type, tier: tu.tier, x: tx, y: ty2, range: rg };
        var cv = cands.map(view);
        var rid = strat.target(tv, cv);
        for (var i = 0; i < cands.length; i++) if (cands[i].id === rid) { pick = i; break; }
      }
      if (pick < 0) {
        pick = 0;
        var best = cands[0].route.len - cands[0].prog;
        for (var i = 1; i < cands.length; i++) { var rm = cands[i].route.len - cands[i].prog; if (rm < best) { best = rm; pick = i; } }
      }
      var tg = cands[pick], tgp = cpos[pick];
      var dm = tdmg(tu);
      var hit = [];
      if (td.splash > 0) {
        var sr = td.splash * td.splash;
        for (var i = 0; i < enemies.length; i++) {
          var e = enemies[i];
          if (e.hp <= 0) continue;
          if (e.air ? !td.air : !td.ground) continue;
          var p = posAt(e.route, e.prog);
          var dx = p[0] - tgp[0], dy = p[1] - tgp[1];
          if (dx * dx + dy * dy <= sr) hit.push(e);
        }
      } else hit.push(tg);
      for (var i = 0; i < hit.length; i++) {
        var e = hit[i];
        e.hp -= td.pierce ? dm : Math.max(1, dm - e.armor);
        if (td.slow) e.slow = td.slow;
      }
      tu.cd = td.per;
      if (obs && obs.shot) obs.shot(tick, s, tu.type, tu.tier, tg.id, tgp[0], tgp[1], rg);
      var rem = [], spawned = [];
      for (var i = 0; i < enemies.length; i++) {
        var e = enemies[i];
        if (e.hp <= 0) {
          gold += ET[e.type].bounty;
          log.push([tick, 'K', e.id, s]);
          var kp = posAt(e.route, e.prog);
          var ids = [];
          if (e.type === 'splitter') {
            var sh = Math.max(1, Math.floor(e.maxHp / 4));
            for (var q = 0; q < 3; q++) { var ne = mkEnemy('splitling', e.wave, sh, e.prog); spawned.push(ne); ids.push(ne.id); }
          }
          if (obs && obs.kill) obs.kill(tick, e, kp[0], kp[1], s, ids);
        } else rem.push(e);
      }
      enemies = rem.concat(spawned);
    }
    for (var i = 0; i < enemies.length; i++) if (enemies[i].slow > 0) enemies[i].slow--;
    if (obs && obs.tickEnd) obs.tickEnd(tick, { enemies: enemies, turrets: turrets, gold: gold, baseHp: baseHp, wave: curWave, posAt: posAt });
  }
  var endTick = fallTick >= 0 ? fallTick : maxTicks;
  return { score: Math.round((endTick - 20) / 40 * 100) / 100, fallTick: fallTick, log: log, hash: hash(log) };
}
