      }
      if (pick < 0) {
        pick = 0;
        var best = cands[0].route.len - cands[0].prog;
        for (var i = 1; i < cands.length; i++) { var rm = cands[i].route.len - cands[i].prog; if (rm < best) { best = rm; pick = i; } }
      }
