function createStrategy() {
  // Fixed, search-optimised build/upgrade order executed greedily as gold allows.
  var ORDER = %%GENOME%%;
  var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  var ptr = 0;
  return {
    plan: function (s) {
      var acts = [];
      var g = s.gold;
      var occ = s.slots.map(function (x) { return x.turret ? { type: x.turret.type, tier: x.turret.tier } : null; });
      while (ptr < ORDER.length && acts.length < 32) {
        var it = ORDER[ptr];
        if (it[0] === 'b') {
          if (occ[it[1]]) { ptr++; continue; }
          var c = COST[it[2]];
          if (g < c) break;
          g -= c; occ[it[1]] = { type: it[2], tier: 1 };
          acts.push({ op: 'build', slot: it[1], type: it[2] });
        } else {
          var o = occ[it[1]];
          if (!o || o.tier >= 3) { ptr++; continue; }
          var uc = COST[o.type] * (o.tier === 1 ? 1 : 2);
          if (g < uc) break;
          g -= uc; o.tier++;
          acts.push({ op: 'upgrade', slot: it[1] });
        }
        ptr++;
      }
      return acts;
    }
  };
}

