function createStrategy() {
  // Build / upgrade / sell order found by offline search over many seeds (never on seed 42),
  // executed greedily as gold allows; plus a per-turret-type targeting rule.
  var PLAN = %%GENOME%%;
  var ORDER = PLAN.order, MODES = PLAN.modes;
  var TYPES = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
  var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  var ptr = 0;
  return {
    plan: function (s) {
      var acts = [];
      var g = s.gold;
      var occ = s.slots.map(function (x) { return x.turret ? { type: x.turret.type, tier: x.turret.tier, spent: x.turret.spent } : null; });
      while (ptr < ORDER.length && acts.length < 32) {
        var it = ORDER[ptr];
        if (it[0] === 'b') {
          if (occ[it[1]]) { ptr++; continue; }
          var c = COST[it[2]];
          if (g < c) break;
          g -= c; occ[it[1]] = { type: it[2], tier: 1, spent: c };
          acts.push({ op: 'build', slot: it[1], type: it[2] });
        } else if (it[0] === 'u') {
          var o = occ[it[1]];
          if (!o || o.tier >= 3) { ptr++; continue; }
          var uc = COST[o.type] * (o.tier === 1 ? 1 : 2);
          if (g < uc) break;
          g -= uc; o.tier++; o.spent += uc;
          acts.push({ op: 'upgrade', slot: it[1] });
        } else {
          var o2 = occ[it[1]];
          if (o2) { g += Math.floor(o2.spent * 70 / 100); occ[it[1]] = null; acts.push({ op: 'sell', slot: it[1] }); }
        }
        ptr++;
      }
      return acts;
    },
    target: function (t, cs) {
      var m = MODES[TYPES.indexOf(t.type)];
      if (!m) return -1;
      var best = -1, bv = -Infinity;
      for (var i = 0; i < cs.length; i++) {
        var e = cs[i], v;
        if (m === 1) v = e.hp;
        else if (m === 2) v = -e.hp;
        else if (m === 3) v = (e.slowed ? 0 : 1e6) - e.remaining;
        else if (m === 4) v = e.armor * 1e6 - e.remaining;
        else if (m === 5) v = e.maxHp * 1e6 - e.remaining;
        else v = -e.remaining;
        if (v > bv) { bv = v; best = e.id; }
      }
      return best;
    }
  };
}

